#pragma unroll
    for (int nf = 0; nf < kNF; ++nf) {
      int nb = nf * 16 + n;
      v4s b = { (short)sB[k0][nb],     (short)sB[k0 + 1][nb],
                (short)sB[k0 + 2][nb], (short)sB[k0 + 3][nb] };
